const {Q,F}=require('../author.cjs'),id='ips';
const q=(n,obj,stem,a,b,c,section,solution)=>Q('ips-'+n,id,'portfolio','practice',obj,stem,[a,b,c],0,solution||[a[1],b[1]+' '+c[1]],{section});
const N=(n,obj,stem,texts,why,tex,reading,meaning,section)=>Q('ips-'+n,id,'portfolio','practice',obj,stem,texts.map((s,i)=>[s,why[i]]),0,[F(tex,reading,[['Z',meaning]]),why[0]],{section});
module.exports=[
 q('01','a','The primary purpose of a written investment policy statement is to:',['Translate the investor situation into an agreed basis for investment decisions and review.','Der schriftliche Auftrag verbindet Anlegerziele und Grenzen mit Auswahl und Kontrolle.'],['Guarantee that the portfolio will not lose money.','Eine dokumentierte Regel kann Marktrisiken nicht ausschalten.'],['Select the highest-return fund before investor information is collected.','Die Produktauswahl braucht zuerst die Anlegergrundlage.'],'purpose'),
 q('02','a','A client defines capital preservation in purchasing-power terms, while the manager interprets it in nominal EUR. The IPS should first:',['Clarify the unit, horizon and intended objective.','Kaufkraft und nominaler Betrag sind verschiedene Zielgrößen; der Begriff wird vor der Anlageentscheidung präzisiert.'],['Treat both statements as identical because they use the word preservation.','Dasselbe Wort macht die wirtschaftlichen Ziele nicht identisch.'],['Replace the client objective with the manager latest forecast.','Eine Prognose ist kein vereinbartes Anlegerziel.'],'purpose'),
 q('03','a','A written IPS is particularly useful during a manager transition because it:',['Preserves the agreed objectives, constraints and delegated responsibilities.','Die Dokumentation macht den bestehenden Auftrag über einzelne Personen hinaus nachvollziehbar.'],['Requires the new manager to adopt the previous manager favorite securities.','Die konkreten Titel müssen nicht dauerhaft unverändert bleiben.'],['Eliminates transaction costs during the transition.','Die Schriftform beseitigt keine Spannen, Steuern oder Gebühren.'],'discipline'),
 q('04','a','A market decline occurs while client circumstances and the mandate remain unchanged. A useful IPS most directly supports:',['Reviewing the decline under previously agreed rules before changing the plan.','Die Regel begrenzt impulsive Änderungen; gleichzeitig bleiben Grenzen und Annahmen überprüfbar.'],['Automatically treating every decline as a new client objective.','Eine Marktbewegung ist nicht automatisch eine neue Anlegerverpflichtung.'],['Ignoring every future material change in client circumstances.','Disziplin bedeutet keine Unveränderlichkeit bei neuen Tatsachen.'],'discipline'),
 q('05','a','An investor brings retirement forward by five years. The most appropriate use of the IPS is to:',['Reassess the changed contribution and withdrawal schedule and amend the mandate through its review process.','Der neue Zeitpfad kann Ziele, Liquidität und Tragfähigkeit verändern.'],['Retain every old assumption because a written policy can never change.','Ein IPS muss relevante Änderungen berücksichtigen können.'],['Treat the earlier retirement as proof that higher returns are available.','Der neue Bedarf verändert nicht automatisch das Marktangebot.'],'discipline'),
 q('06','a','A portfolio loses value but remains within its agreed risks and restrictions. The loss alone:',['Does not establish that the manager breached the IPS.','Regelkonformität und negatives Marktergebnis sind getrennt zu prüfen.'],['Proves that the IPS was violated.','Ein zugelassenes Risiko kann sich ungünstig realisieren.'],['Proves that every assumption and action was appropriate.','Auch ohne bewiesene Grenzverletzung müssen Annahmen und Umsetzung überprüft werden.'],'purpose'),
 q('07','a','After poor results, an IPS can help distinguish:',['A changed investor need, a forecast error and an implementation breach.','Die dokumentierte frühere Grundlage erlaubt eine sachliche Ursachenprüfung.'],['Only the identity of the security with the best hindsight return.','Eine nachträgliche Rangliste erklärt nicht den gesamten Entscheidungsprozess.'],['Guaranteed losses from guaranteed profits.','Eine solche Garantie folgt aus dem Dokument nicht.'],'purpose'),
 q('08','a','A client has several accounts managed by different teams. The written policy is most helpful when it:',['Defines which assets are covered and how relevant outside exposures enter the total analysis.','Der Mandatsumfang und die wirtschaftliche Gesamtposition müssen erkennbar sein.'],['Assumes that risks outside each team account cannot affect the investor.','Außerhalb liegende Konzentration und Verpflichtungen können trotzdem relevant sein.'],['Classifies each account name as an independent asset class.','Kontonamen belegen keine unabhängigen wirtschaftlichen Risiken.'],'scope'),
 q('09','a','The IPS reduces disagreement most directly by:',['Documenting the meaning of objectives and how decisions will be evaluated.','Messbasis und gemeinsame Erwartungen werden vor der späteren Ergebnisbeurteilung geklärt.'],['Promising that all parties will forecast identical returns forever.','Die Schriftform erzwingt keine identischen Zukunftserwartungen.'],['Preventing the client from ever supplying new information.','Neue Informationen können gerade eine Aktualisierung auslösen.'],'purpose'),
 q('10','a','A complete product brochure is offered as a replacement for collecting investor objectives. The most appropriate conclusion is:',['Product information does not establish the investor individual mandate.','Produktmerkmale beantworten nicht automatisch, wann der Anleger welche Zahlung benötigt.'],['The brochure must define every client risk capacity.','Die finanzielle Fähigkeit hängt von der jeweiligen Gesamtsituation ab.'],['The product expected return overrides all client constraints.','Ein unsicherer Mittelwert setzt keine Grenze außer Kraft.'],'purpose'),
 q('11','a','A written IPS should be regarded as:',['A revisable decision and communication framework with documented authority.','Es schafft Kontinuität und einen erkennbaren Weg für begründete Änderungen.'],['A forecast contract requiring financial markets to deliver a fixed return.','Märkte sind keine Partei einer Renditezusage des Dokuments.'],['A substitute for checking suitability after material client changes.','Eine relevante Änderung kann die Eignung des bisherigen Auftrags verändern.'],'discipline'),
 q('12','a','Which statement best describes the relationship between planning and investment selection?',['Selection should be evaluated against the previously specified investor requirements.','Der Auftrag liefert die Grundlage der Eignungsprüfung.'],['A successful recent fund should determine the investor future cash needs.','Eine Fondsrendite bestimmt keine persönliche Zahlungspflicht.'],['A policy is useful only after a loss has already occurred.','Die Regeln sollen vorab Entscheidungen leiten und später überprüfbar machen.'],'purpose'),
 q('13','b','Which combination belongs most directly in an IPS?',['Objectives, constraints, responsibilities and review rules.','Diese Informationen verbinden den wirtschaftlichen Auftrag mit Umsetzung und Kontrolle.'],['Only a list of recent winning securities.','Eine Titelliste enthält weder vollständige Ziele noch Entscheidungsregeln.'],['Only a manager marketing description.','Anbieterinformationen ersetzen den individuellen Auftrag nicht.'],'scope'),
 q('14','b','An IPS states an illiquid-investment limit of 10% but gives no measurement basis. The most important missing information is:',['The covered holdings, valuation basis, denominator and review procedure.','Ohne diese Angaben ist nicht eindeutig, ob eine konkrete Position die Grenze verletzt.'],['A prediction of the next best-performing asset.','Die Prognose klärt den Nenner des Limits nicht.'],['A guarantee that all illiquid assets can be sold immediately.','Eine solche Garantie folgt aus der Prozentangabe nicht.'],'governance'),
 q('15','b','An allocation rule refers to an appendix. The governance process should most directly establish:',['The applicable version, approval and priority if documents conflict.','Nur so ist die tatsächlich gültige Regel rekonstruierbar.'],['That every draft appendix automatically overrides the approved IPS.','Ein Entwurf besitzt nicht ohne geregelte Genehmigung Vorrang.'],['That references make review unnecessary.','Auch referenzierte Regeln müssen überprüft werden.'],'scope'),
 q('16','b','A risk limit is breached passively after market movements. A well-specified IPS should explain:',['Who measures the breach and who decides the permitted response and timing.','Messung, Zuständigkeit und Umgang mit passiven Verletzungen werden vorab festgelegt.'],['That a forced immediate sale is universally required by any percentage limit.','Ein Prozentwert legt allein weder Frist noch Transaktionsweg fest.'],['That the denominator may always be changed retroactively to remove the breach.','Eine nachträgliche Neudefinition verschleiert die ursprüngliche Regel.'],'governance'),
 q('17','b','The mandate gives a committee authority to change strategic weights and a manager authority to select securities within limits. This primarily specifies:',['Delegated decision responsibilities.','Es wird abgegrenzt, welche Entscheidung wer treffen darf.'],['A guaranteed level of return.','Zuständigkeit ist keine Ertragszusage.'],['The tax treatment of all possible future transactions.','Eine Delegationsregel ersetzt keine Steueranalyse.'],'governance'),
 q('18','b','A performance-review section should most directly specify:',['The benchmark, measurement basis, reporting and review arrangements.','Die Ergebnisbeurteilung braucht einen passenden vorher definierten Vergleich und Ablauf.'],['A benchmark chosen only after the manager return is known.','Eine nachträgliche Auswahl kann die Beurteilung verzerren.'],['Only the manager highest return in any currency.','Währung und Zeitraum müssen zum Auftrag passen.'],'scope'),
 q('19','b','An IPS specifies client tax status. The most appropriate interpretation is that it:',['Provides relevant information for after-tax implementation under applicable rules.','Der Status beeinflusst die tatsächlich verfügbare Rendite; konkrete Regeln werden gesondert geprüft.'],['Creates the same tax rule in every jurisdiction.','Der Auftrag vereinheitlicht keine nationalen Vorschriften.'],['Makes pretax and after-tax performance identical.','Steuerzahlungen können den verfügbaren Ertrag verändern.'],'taxes'),
 q('20','b','Which statement about IPS format is most accurate?',['The format can vary while material objectives and constraints remain clear.','Ein privates und ein institutionelles Mandat können unterschiedlich umfangreich dokumentiert sein.'],['Every investor must use one identical universal table.','Die wirtschaftlich notwendigen Informationen verlangen keine weltweit identische Vorlage.'],['A short document may omit all relevant withdrawal dates.','Kürze rechtfertigt keine fehlenden entscheidenden Fälligkeiten.'],'scope'),
 q('21','b','The scope section of a household mandate should most directly identify:',['The covered accounts and relevant outside assets or obligations.','Der unmittelbar verwaltete Bestand wird vom wirtschaftlich mitzuberücksichtigenden Zusammenhang unterschieden.'],['Only the adviser preferred investment website.','Eine Informationsquelle definiert nicht den Mandatsumfang.'],['Only the daily change of one exchange index.','Ein Marktstand benennt weder Anleger noch Konten und Verpflichtungen.'],'scope'),
 q('22','b','A client changes an investment restriction. The IPS process should most appropriately record:',['The authorized change and its effective version.','Die spätere Prüfung muss erkennen können, ab wann welche Regel galt.'],['That the new restriction applied to every decision before approval.','Eine rückwirkende Behauptung darf frühere Entscheidungen nicht verschleiern.'],['Only the manager expected benefit, without client authorization.','Ein erwarteter Vorteil ersetzt den erforderlichen Änderungsweg nicht.'],'discipline'),
 q('23','b','A statement that risk should be reasonable is improved most directly by:',['Defining the relevant risk measure, horizon and decision procedure.','Die quantitative oder qualitative Konkretisierung macht die Vorgabe prüfbar.'],['Adding more product names without explaining risk.','Mehr Namen lösen die Mehrdeutigkeit nicht.'],['Promising no uncertainty under any future conditions.','Ein unbegründetes Versprechen schafft kein ausführbares Risikolimit.'],'risk-objectives'),
 q('24','b','A policy requires portfolio review after a material client event as well as periodic monitoring. This most directly specifies:',['Triggers for reassessment.','Der Ablauf verbindet regelmäßige Kontrolle mit wesentlichen neuen Tatsachen.'],['An instruction to change strategic weights after every daily price move.','Überprüfung und automatische Änderung sind verschiedene Handlungen.'],['A prohibition on documenting new liabilities.','Neue Verpflichtungen können gerade eine Überprüfung auslösen.'],'discipline'),
 N('25','c','A portfolio earns 5% nominal net return while inflation is 3%. The real return is closest to:',['1.94175%.','2.00000%.','8.15000%.'],['Die nominalen und realen Wachstumsfaktoren werden über das Preisniveau verknüpft.','Das ist nur die Differenznäherung.','Das multipliziert die Inflation in die falsche Richtung.'],'Z=1{,}05/1{,}03-1\\approx0{,}0194175','Aus 105 nominalen Endeinheiten werden durch Division durch 1,03 Einheiten heutiger Kaufkraft.','Reale jährliche Nettorendite als Dezimalrate; die Antworten sind in Prozent.','return-basis'),
 N('26','c','A client requires 2% real net return with inflation of 3%. The required nominal net return is:',['5.06%.','5.00%.','1.94%.'],['Reales Wachstum und Preisniveau werden als Faktoren multipliziert.','Das ignoriert den Kreuzterm von 0,06 Prozentpunkten.','Das würde einen nominalen Ertrag real deflationieren statt ein reales Ziel nominal fortzuschreiben.'],'Z=1{,}02\\cdot1{,}03-1=0{,}0506','Das reale Endziel 102 benötigt bei drei Prozent Inflation 105,06 nominale Einheiten.','Erforderliche nominale Nettorendite als Dezimalrate.','return-basis'),
 N('27','c','Without contributions or withdrawals, EUR 100,000 must become EUR 150,000 in ten years. The constant annual net rate is closest to:',['4.13797%.','5.00000%.','50.00000%.'],['Die zehnte Wurzel verteilt den Endfaktor geometrisch.','Das verteilt den Gesamtzuwachs linear und ignoriert Zinseszins.','Das ist der gesamte Zehnjahreszuwachs, nicht die Jahresrate.'],'Z=1{,}5^{1/10}-1\\approx0{,}0413797','Der Faktor 1,5 muss sich aus zehn gleichen Jahresfaktoren ergeben.','Erforderliche konstante jährliche Nettorendite.','required-return'),
 N('28','c','The same increase from EUR 100,000 to EUR 150,000 is delayed from ten to twenty years, with no other cashflows. The new annual net rate is closest to:',['2.04802%.','2.06899%.','4.13797%.'],['Die zwanzigste Wurzel verwendet den neuen Horizont.','Das halbiert die frühere Jahresrate statt den Endfaktor neu zu zerlegen.','Das behält den alten Zehnjahreshorizont bei.'],'Z=1{,}5^{1/20}-1\\approx0{,}0204802','Zinseszins ist multiplikativ; die neue Rate ist nicht exakt halb so groß wie zuvor.','Erforderliche konstante jährliche Nettorendite für zwanzig Jahre.','required-return'),
 N('29','c','A nominal net target is 5.06%. A 1% fee applies to wealth after gross return; then 25% tax applies to the remaining positive gain. Required gross return is closest to:',['7.82492%.','6.06000%.','31.06000%.'],['Zuerst die Steuer auf den Gewinn, danach die Gebühr auf den Vermögensfaktor rückwärts aufheben.','Das addiert nur einen Gebührenpunkt und ignoriert Steuer und Gebührenbasis.','Das addiert einen Steuersatz zum Ziel, obwohl die Steuer nur den Gewinn betrifft.'],'Z=\\frac{1+0{,}0506/0{,}75}{0{,}99}-1\\approx0{,}0782492','Probe: 100 werden brutto etwa 107,8249, nach Gebühr 106,7467 und nach Steuer 105,06.','Benötigte Bruttorendite im ausdrücklich beschriebenen Einjahresmodell.','fees-taxes'),
 N('30','c','Initial wealth is EUR 100,000. A fixed EUR 4,000 is withdrawn at year-end, after return. Remaining wealth must equal EUR 103,000. Required net return is:',['7%.','4%.','3%.'],['Ertrag muss sowohl die feste Endzahlung als auch den höheren Restbestand finanzieren.','Vier Prozent ersetzen nur die Auszahlung und lassen nominal 100.000 übrig.','Drei Prozent finanzieren nur den Zielzuwachs, ohne die Entnahme zu ersetzen.'],'Z=(103\\,000+4\\,000)/100\\,000-1=0{,}07','Vor der Entnahme werden 107.000 gebraucht; bezogen auf 100.000 Anfangskapital sind dies sieben Prozent.','Erforderliche jährliche nominale Nettorendite.','withdrawals'),
 N('31','c','A fund returns -18% while its benchmark returns -20% over the same period and currency. Active return is:',['+2 percentage points.','-2 percentage points.','+10 percentage points.'],['Die Differenz ist minus achtzehn minus minus zwanzig.','Das kehrt Portfolio und Benchmark um.','Das teilt die Verluste relativ zueinander statt Renditen zu subtrahieren.'],'Z=-0{,}18-(-0{,}20)=0{,}02','Die aktive Rendite ist positiv, obwohl der absolute Anlegerverlust achtzehn Prozent beträgt.','Aktive Periodenrendite als Dezimalrate; 0,02 entspricht zwei Prozentpunkten.','relative-risk'),
 N('32','c','After a 20% loss and with no external cashflows, the gain required to restore initial nominal wealth is:',['25%.','20%.','80%.'],['Zwanzig fehlende Einheiten werden auf die verbleibenden achtzig bezogen.','Ein erneuter Gewinn von zwanzig Prozent ergäbe nur 96 aus ursprünglich hundert.','Achtzig Prozent ist der verbliebene Vermögensanteil, nicht der Aufholgewinn.'],'Z=0{,}20/(1-0{,}20)=0{,}25','Die kleinere Bezugsbasis macht erforderlichen Aufholgewinn und vorherigen Verlust asymmetrisch.','Erforderlicher relativer Gewinn auf den nach dem Verlust verbleibenden Bestand.','risk-objectives'),
 q('33','c','A client required return exceeds every plausible expected return within the agreed limits. The most appropriate response is to:',['Reassess contributions, target size, timing and genuinely permissible risks.','Die Lücke ist ein Planungsproblem; verschiedene wirtschaftliche Stellgrößen werden überprüft.'],['Increase the forecast until the plan appears feasible without further justification.','Eine unbewiesene Prognoseänderung erzeugt keine zusätzliche Finanzierung.'],['Treat the required rate as a guaranteed future return.','Eine Anforderung ist keine Ertragszusage.'],'objectives'),
 q('34','c','One annual active return of +2 percentage points is observed. Which conclusion is most appropriate?',['That observation alone does not establish tracking error.','Tracking Error misst Streuung; ein einzelner relativer Wert beschreibt keine belastbare Verteilung.'],['Tracking error must equal +2 percentage points.','Mittelwert oder Einzelwert und Standardabweichung sind verschieden.'],['The portfolio cannot have suffered an absolute loss.','Auch ein starker relativer Vorsprung kann mit Verlust einhergehen.'],'relative-risk'),
 q('35','c','Which risk objective most directly addresses a known near-term fixed payment?',['A criterion tied to the amount available at that payment date, with explicit assumptions.','Die Anlegerverpflichtung betrifft Betrag und Zeitpunkt; das Risikoziel sollte dazu passen.'],['Only the rank of the fund past monthly return.','Die Rangliste sagt nichts über die sichere verfügbare Zahlung.'],['Only relative return versus an equity index, regardless of absolute loss.','Ein relativer Vorsprung kann den festen Betrag trotzdem unterschreiten.'],'risk-objectives'),
 q('36','c','Which statement best distinguishes a mean return from a target payment?',['An expected return is uncertain and does not promise the needed dated cash amount.','Der Mittelwert einer Verteilung ist keine vertragliche Mindestzahlung.'],['A positive expected return excludes all losses.','Positive Erwartung und negative Einzelzustände können gleichzeitig bestehen.'],['A required target changes market opportunities automatically.','Der Bedarf des Kunden schafft keine sichere Marktverzinsung.'],'objectives'),
 q('37','d','Investor A has more wealth than investor B but nearly all of it is committed to a fixed payment next year. The most appropriate conclusion is:',['A may have less financial risk capacity despite greater wealth.','Die verfügbaren Puffer relativ zur Verpflichtung sind entscheidend.'],['A must have greater capacity solely because wealth is higher.','Das isolierte Vermögensranking ignoriert die bevorstehende Zahlung.'],['B can bear unlimited losses because no payment next year is stated.','Fehlende Angaben begründen keine unbegrenzte Tragfähigkeit.'],'capacity'),
 q('38','d','An investor is psychologically comfortable with a large loss but could not meet a fixed obligation after that loss. This most directly indicates:',['High stated willingness can coexist with limited capacity.','Psychologische Zustimmung und finanzielle Zahlungssicherheit sind unterschiedliche Dimensionen.'],['Willingness creates the cash needed for the obligation.','Eine Haltung ist kein Mittelzufluss.'],['Capacity is determined only by the questionnaire answer.','Die wirtschaftlichen Folgen brauchen eine eigene Prüfung.'],'conflict'),
 q('39','d','An investor can financially sustain substantial losses but would abandon the plan after a modest decline. The adviser should:',['Clarify understanding and actual willingness before selecting the risk level.','Hohe Fähigkeit allein macht einen psychologisch nicht getragenen Auftrag nicht sinnvoll.'],['Automatically invest at the maximum financially affordable risk.','Das ignoriert die tatsächliche Bereitschaft und mögliche Planabbrüche.'],['Conclude that explanations can never affect risk understanding.','Aufklärung kann Irrtümer korrigieren, erzwingt aber keine höhere Bereitschaft.'],'willingness'),
 q('40','d','A long working horizon most strongly supports risk capacity when considered together with:',['The stability and market dependence of future income and the investor commitments.','Zeit allein genügt nicht; gemeinsame schlechte Zustände und Zahlungsbedarf zählen.'],['The assumption that all salary is immediately tradable at its estimated present value.','Geschätztes Humankapital ist nicht automatisch liquide verfügbar.'],['The rule that younger investors can never suffer permanent losses.','Ein früher Lebensabschnitt schließt wirtschaftliche Verluste nicht aus.'],'capacity'),
 N('41','d','A client agrees to consider a 10% loss on a EUR 2 million portfolio. The corresponding monetary loss is:',['EUR 200,000.','EUR 20,000.','EUR 2,000,000.'],['Zehn Prozent werden auf das betroffene Gesamtvermögen bezogen.','Das entspricht nur einem Prozent des Vermögens.','Das wäre ein vollständiger Verlust.'],'Z=0{,}10\\cdot2\\,000\\,000=200\\,000','Die Umrechnung macht die abstrakte Prozentangabe als konkreten Geldbetrag besprechbar; sie beweist noch keine Tragfähigkeit.','Euroverlust im ausdrücklich angenommenen Szenario.','willingness'),
 q('42','d','When willingness and capacity conflict, overall risk tolerance should most appropriately:',['Reflect the binding limitation after clarification of the investor circumstances.','Die engere tatsächliche Begrenzung darf nicht durch einen unbegründeten Durchschnitt überspielt werden.'],['Always equal the arithmetic mean of two uncalibrated questionnaire categories.','Qualitative Kategorien besitzen nicht automatisch eine gemeinsame numerische Skala.'],['Always equal the higher of the two assessments.','Die höhere Angabe beseitigt die andere Begrenzung nicht.'],'conflict'),
 q('43','d','A client financial ability to take risk improves most directly when, all else equal:',['A fixed liability is reduced and more uncommitted resources remain.','Die geringere Verpflichtung kann den wirtschaftlichen Verlustpuffer vergrößern.'],['The client expresses more optimism without any economic change.','Optimismus verändert zunächst die Haltung, nicht die verfügbaren Mittel.'],['An illiquid asset is renamed a cash substitute without changing its redemption rights.','Eine Umbenennung verändert keine wirtschaftliche Verfügbarkeit.'],'capacity'),
 q('44','d','A client needs a high return but has very limited loss capacity. The adviser should recognize:',['A possible inconsistency in the funding plan.','Der hohe Bedarf und die geringe Verlusttragfähigkeit können gleichzeitig bestehen und Anpassungen verlangen.'],['That need alone makes a high-risk portfolio suitable.','Ein Ziel ersetzt keine Fähigkeit, ungünstige Ergebnisse zu tragen.'],['That the required rate guarantees a recovery after losses.','Die Zielrechnung verspricht keinen Marktverlauf.'],'conflict'),
 q('45','d','A questionnaire answer made during a strong bull market should be treated as:',['One input to a broader assessment using concrete loss scenarios and discussion.','Die Stabilität der Antwort und das Verständnis wirtschaftlicher Folgen werden zusätzlich geprüft.'],['An irrevocable lifetime authorization for maximum risk.','Eine aktuelle Antwort ersetzt keine spätere Neubewertung.'],['Proof that the client future income is independent of markets.','Eine Präferenzangabe liefert keine Einkommenskorrelation.'],'willingness'),
 q('46','d','A client has concentrated employer shares and employment income from the same company. Financial capacity analysis should:',['Consider the possibility that income and wealth deteriorate together.','Gemeinsame Unternehmensrisiken können den verfügbaren Puffer im selben Zustand vermindern.'],['Assume salary always offsets any loss in employer shares.','Der gegenteilige gemeinsame Verlauf ist möglich.'],['Treat familiarity with the employer as a guarantee of payment.','Vertrautheit macht weder Gehalt noch Aktienwert sicher.'],'capacity'),
 q('47','d','Education about a misunderstood loss scenario most appropriately aims to:',['Improve informed understanding while respecting the resulting genuine willingness.','Aufklärung kann eine falsche Vorstellung verändern; sie ist keine erzwungene Risikoerhöhung.'],['Replace the investor preference with the adviser preference automatically.','Die Anlegerhaltung wird nicht durch die eigene Vorliebe des Beraters ersetzt.'],['Create financial resources solely by changing questionnaire language.','Bessere Worte schaffen keine zusätzlichen Zahlungspuffer.'],'willingness'),
 q('48','d','Which fact most directly concerns willingness rather than financial capacity?',['The investor stated emotional response to a plausible drawdown.','Die persönliche Reaktion beschreibt die Haltung gegenüber Verlust.'],['The amount of a fixed payment due next month.','Die Fälligkeit beeinflusst die wirtschaftliche Fähigkeit.'],['The amount of available uncommitted cash.','Dieser Betrag ist eine finanzielle Ressource.'],'willingness'),
 N('49','e','A EUR 40,000 payment is due in six months. EUR 20,000 cash and EUR 10,000 expected net income are available by then. Before other financing, the base-case shortfall is:',['EUR 10,000.','EUR 20,000.','EUR 30,000.'],['Die beiden zeitgerecht verfügbaren Ressourcen werden vom Zahlungsbedarf abgezogen.','Das ignoriert den angegebenen Einkommenszufluss.','Das ist die Summe der Ressourcen, nicht die Lücke.'],'Z=40\\,000-20\\,000-10\\,000=10\\,000','Die Rechnung setzt den Einkommenszufluss ausdrücklich voraus; dessen Unsicherheit muss daneben geprüft werden.','Ungedeckter Eurobetrag zum genannten Termin.','liquidity'),
 q('50','e','A foundation has a perpetual legal existence and annual grant payments. Its horizon analysis should:',['Combine the long existence with the recurring dated liquidity needs.','Dauerhorizont und jährliche Verpflichtungen können nebeneinander bestehen.'],['Treat all assets as never needed because the foundation does not expire.','Die jährlichen Förderungen benötigen trotzdem verfügbare Mittel.'],['Assume every asset can be sold at a stable value on demand.','Der Bestandshorizont schafft keine allgemeine Handelbarkeitsgarantie.'],'horizon'),
 q('51','e','A listed asset is readily tradable but its price is uncertain. For a fixed payment next month it:',['Offers sale access without guaranteeing the required sale proceeds.','Marktzugang und Sicherheit eines konkreten Zahlungsbetrags sind verschieden.'],['Must provide exactly the required amount because it is listed.','Eine Börsennotierung fixiert keinen künftigen Preis.'],['Has no relevant liquidity advantage over every locked private investment.','Verkäuflichkeit kann vorteilhaft sein, auch wenn der Erlös unsicher bleibt.'],'liquidity'),
 N('52','e','EUR 100 earns 6% annually for ten years. Each positive annual gain is immediately taxed at an assumed 25%, with no costs. End wealth is closest to:',['EUR 155.2969.','EUR 159.3136.','EUR 179.0848.'],['Jährlich bleiben 4,5 Prozent für die Wiederanlage.','Das gehört zum anderen Modell mit Steuer erst auf den Endgewinn.','Das ist das Vorsteuervermögen ohne Steuerabzug.'],'Z=100[1+0{,}06(1-0{,}25)]^{10}\\approx155{,}2969','Die jährlich abgeführte Steuer steht im Folgejahr nicht für die Wiederanlage zur Verfügung.','Endvermögen in Euro nach der beschriebenen laufenden Modellsteuer.','taxes'),
 N('53','e','EUR 100 earns 6% annually for ten years. Only the final positive cumulative gain is taxed at an assumed 25%, with no interim tax or costs. End wealth is closest to:',['EUR 159.3136.','EUR 134.3136.','EUR 155.2969.'],['Anfangskapital plus 75 Prozent des kumulierten Gewinns bleiben erhalten.','Das besteuert fälschlich auch das Anfangskapital.','Das wäre laufende jährliche Gewinnbesteuerung.'],'Z=100+0{,}75[100(1{,}06)^{10}-100]\\approx159{,}3136','Die Steuerbasis ist ausdrücklich nur der positive Endgewinn, nicht das gesamte Endvermögen.','Endvermögen in Euro nach der beschriebenen einmaligen Endgewinnsteuer.','taxes'),
 q('54','e','A hypothetical mandate prohibits borrowing. A proposed allocation is 120% equities and -20% cash. The allocation:',['Violates the stated borrowing restriction despite weights summing to one.','Negatives Cash finanziert im Modell den über hundert Prozent liegenden Aktienbestand.'],['Complies because the weights sum to 100%.','Die Summenbedingung allein prüft keine Kreditgrenze.'],['Contains no leverage because cash is an asset class.','Das negative Vorzeichen zeigt hier die Finanzierung.'],'law'),
 q('55','e','A client agrees to a transaction that violates an applicable binding legal restriction. The agreement:',['Does not by itself remove the legal restriction.','Persönliche Zustimmung setzt eine verbindliche anwendbare Vorschrift nicht außer Kraft.'],['Automatically makes every otherwise prohibited instrument permissible.','Der Kundenwunsch kann nicht pauschal geltendes Recht aufheben.'],['Proves that the transaction has no financial risk.','Rechtliche Zustimmung und finanzielle Risikolosigkeit sind verschiedene Fragen.'],'law'),
 q('56','e','A client objects to investing in a specified activity for personal reasons. The IPS should most directly:',['State an executable restriction and assess its interaction with other objectives.','Die Präferenz wird in erkennbare Regeln übersetzt und mit Streuung und Zielen abgestimmt.'],['Assume the objection guarantees higher future returns.','Ein Wertewunsch ist keine Renditeprognose.'],['Ignore the preference whenever a manager likes a valuation.','Eine gültige Grenze wird nicht allein durch eine Kaufmeinung aufgehoben.'],'unique'),
 q('57','e','Which is most appropriately treated as a material unique circumstance?',['A large nontradable family-business holding that affects total exposure.','Der außerhalb liegende Bestand kann die geeignete Ergänzung im Mandat verändern.'],['A temporary broad market-price movement affecting all comparable investors.','Das ist zunächst eine allgemeine Marktbewegung und kein besonderer anlegerspezifischer Umstand.'],['A standard reporting interval that creates no unusual client requirement.','Ein gewöhnliches Berichtsintervall ohne besondere Anforderung ist hier nicht die genannte ungewöhnliche wirtschaftliche Konzentration.'],'unique'),
 q('58','e','A client has a high expected-return investment with redemptions only every three years, but needs all invested money in one year. With no other resources, the expectation:',['Does not solve the stated liquidity mismatch.','Eine hohe erwartete Verzinsung schafft keinen früheren vertraglichen Rückgabezeitpunkt.'],['Makes the three-year lockup irrelevant.','Die Rückgaberegel gilt unabhängig vom Mittelwert.'],['Guarantees that borrowing will always be available under stress.','Eine solche Finanzierung muss separat gesichert und geprüft werden.'],'constraints'),
 q('59','e','A policy uses an available credit line to help fund potential capital calls. The most appropriate additional analysis concerns:',['Availability, terms, costs and stress behavior of the line.','Eine bloß genannte Kreditlinie ist ohne ihre Bedingungen kein sicherer Liquiditätspuffer.'],['Only whether the line has an attractive marketing name.','Ein Name ersetzt keine vertraglichen Rechte.'],['The assumption that interest and covenants never apply.','Finanzierungskosten und Bedingungen können entscheidend sein.'],'liquidity'),
 q('60','e','Which statement about constraints is most accurate?',['Their interactions must be assessed for the combined portfolio and payment path.','Mehrere einzeln plausible Grenzen können gemeinsam einen unerfüllbaren Auftrag ergeben.'],['Each constraint can always be satisfied independently without affecting others.','Liquidität, Steuer, Horizont und Konzentration können zusammenwirken.'],['Expected return eliminates the need to check legal and liquidity limits.','Ein Mittelwert ist keine Ausnahme von den geltenden Grenzen.'],'constraints'),
 q('61','f','An ETF is most accurately classified as:',['An investment vehicle whose underlying exposures determine its asset-class characteristics.','Das Vehikel kann unterschiedliche Anlagen enthalten; Börsenhandel definiert nicht deren Risikotreiber.'],['A single asset class with identical risk in every ETF.','Aktien-, Anleihe- und andere ETFs besitzen unterschiedliche Expositionen.'],['Proof that the strategy must be passive.','Auch ein aktiv verwalteter ETF ist möglich.'],'classes'),
 N('62','f','A portfolio is 60% world equity fund with an assumed 65% US weight, plus 40% US equity fund. Effective US exposure is:',['79%.','65%.','100%.'],['Die inneren Regionalanteile werden mit den äußeren Fondsgewichten multipliziert.','Das übernimmt nur den Anteil innerhalb des Weltfonds und ignoriert die zweite Position.','Der Weltfonds enthält im Beispiel auch Nicht-US-Anlagen.'],'Z=0{,}60\\cdot0{,}65+0{,}40\\cdot1=0{,}79','Der Weltfonds trägt 39, der US-Fonds vierzig Prozentpunkte zum Gesamtportfolio bei.','Effektives US-Aktiengewicht im ausdrücklich klassifizierten Beispiel.','overlap'),
 q('63','f','Two different fund names both hold mostly the same equity market. Treating them as nonoverlapping asset classes would most likely:',['Understate the shared exposure.','Unterschiedliche Verpackung oder Namen verhindern keine gemeinsame wirtschaftliche Abhängigkeit.'],['Prove statistical independence.','Unabhängigkeit folgt aus keiner Namenskonvention.'],['Eliminate the need for holdings data.','Gerade die Durchsicht zeigt die tatsächliche Überlappung.'],'overlap'),
 q('64','f','A useful asset-class specification most appropriately considers:',['Similarities within groups, meaningful differences between groups and unintended overlap.','Die Einteilung soll die wirtschaftliche Allokation und gemeinsame Risiken verständlicher machen.'],['Only the alphabetical order of product names.','Die Sortierung beschreibt keine Risikotreiber.'],['The assumption that every distinct manager represents a separate risk source.','Verschiedene Manager können ähnliche Bestände und Faktoren halten.'],'classes'),
 q('65','f','An equity fund is quoted and traded in EUR but holds unhedged foreign assets. The EUR quote:',['Does not by itself eliminate the underlying currency exposure.','Handelswährung und ökonomische Währungsrisiken sind getrennte Eigenschaften.'],['Guarantees a constant EUR value of all foreign holdings.','Eine Notierung ist keine Wechselkurssicherung.'],['Converts all underlying foreign equities into risk-free EUR cash.','Die wirtschaftlichen Ansprüche ändern sich dadurch nicht.'],'currency'),
 N('66','f','An unhedged investment earns 3% in foreign currency, which falls 8% against the home currency. Home-currency return is:',['-5.24%.','-5.00%.','+11.24%.'],['Die beiden Faktoren werden multipliziert; der Wechselkurs ist Heimatwährung je Fremdwährungseinheit.','Das ist die Differenznäherung ohne Kreuzterm.','Das behandelt die Fremdwährungsabwertung mit falschem Vorzeichen.'],'Z=1{,}03\\cdot0{,}92-1=-0{,}0524','Lokaler Ertrag und Währungsänderung wirken auf denselben Endwertfaktor.','Ungehedgte Heimatrendite des angenommenen Jahres.','currency'),
 q('67','f','A private-asset series is valued infrequently and shows low measured correlation with daily equity prices. The analyst should first:',['Examine valuation smoothing, timing and economic common factors.','Zeitversetzte oder geglättete Werte können die beobachtete Streuung und Korrelation beeinflussen.'],['Conclude that the underlying risks must be independent.','Eine niedrige gemessene Korrelation beweist keine Unabhängigkeit.'],['Assume all private assets can be liquidated at the reported value daily.','Die Datenreihe schafft keine täglichen Rückgaberechte.'],'alternatives'),
 q('68','f','For allocating between bonds, a finer classification may be useful because:',['Duration, credit quality and currency can create materially different exposures.','Eine breite Forderungsbezeichnung umfasst verschiedene Zins-, Ausfall- und Währungsrisiken.'],['All bonds have the same risk whenever coupon rates match.','Gleicher Kupon gleicht Laufzeit und Bonität nicht an.'],['Bond fund names determine their covariance matrix.','Gemeinsame Risiken brauchen wirtschaftliche und statistische Informationen.'],'classes'),
 q('69','f','A private-fund commitment is not fully drawn. The allocation process should distinguish:',['Committed amounts, invested values and future liquidity obligations.','Zusage, Marktwert und nächster Zahlungsbedarf sind verschiedene Größen.'],['The commitment as an immediately invested liquid market value in every case.','Kapitalabrufe können erst später stattfinden.'],['All future calls as irrelevant until after they are due.','Eine rechtzeitige Liquiditätsplanung braucht die möglichen Abrufe vorher.'],'alternatives'),
 q('70','f','An asset-class grouping called alternatives combines highly leveraged hedge funds and unlevered direct properties. The most appropriate qualification is:',['The broad label may conceal materially different economic and liquidity risks.','Eine Sammelkategorie macht die enthaltenen Strukturen nicht homogen.'],['The label guarantees identical risk-return behavior.','Die einzelnen Zahlungs- und Hebelstrukturen unterscheiden sich.'],['All constituents must have zero stock-market exposure.','Alternative Strukturen können gemeinsame Aktien- und Kreditfaktoren besitzen.'],'alternatives'),
 q('71','f','The best level of detail for asset-class specification most directly depends on:',['The decisions, relevant exposures, data and implementation needs of the investor.','Granularität soll Entscheidungen verbessern und belastbare Unterschiede sichtbar machen.'],['Maximizing the number of labels regardless of information quality.','Mehr Kategorien allein schaffen keine bessere Analyse.'],['Using the same categories for every investor without regard to obligations.','Währung, Horizont und Zahlungsbedarf können eine andere Abgrenzung erfordern.'],'classes'),
 q('72','f','An active equity mandate and a passive fund track similar broad economic exposures. The most appropriate view is:',['Management style and asset class are distinct dimensions.','Aktiv oder passiv beschreibt die Umsetzung; beide können derselben Aktienklasse angehören.'],['Active management automatically creates a wholly separate asset class.','Der Entscheidungsstil allein entfernt keine gemeinsame Marktexposition.'],['The passive fund has no market risk.','Passivität beseitigt die gehaltenen Aktienrisiken nicht.'],'classes'),
 N('73','g','Expected equity and bond returns are 8% and 3%. With no leverage or other assets, equity weight for 5% expected return is:',['40%.','60%.','62.5%.'],['Die Zielmehrverzinsung zwei Prozentpunkte wird durch den Klassenabstand fünf Prozentpunkte geteilt.','Das ist das resultierende Anleihegewicht.','Das teilt die Zielrendite nur durch die Aktienrendite und ignoriert Anleiheertrag.'],'Z=(0{,}05-0{,}03)/(0{,}08-0{,}03)=0{,}40','Die Ersatzwirkung von Anleihen durch Aktien bestimmt die zusätzliche erwartete Portfoliorendite.','Erforderliches Aktiengewicht für genau den genannten Mittelwert.','allocation'),
 N('74','g','Weights are 40% equities and 60% bonds; volatilities are 20% and 6%, correlation -0.2. Portfolio volatility is closest to:',['8.0895%.','11.6000%.','8.7727%.'],['Die negative Kovarianz wird mit beiden Gewichten berücksichtigt und anschließend die Wurzel gezogen.','Das addiert gewichtete Volatilitäten wie bei perfektem positivem Gleichlauf.','Das lässt den negativen Kreuzterm weg.'],'Z=\\sqrt{0{,}4^2(0{,}20)^2+0{,}6^2(0{,}06)^2+2(0{,}4)(0{,}6)(-0{,}2)(0{,}20)(0{,}06)}\\approx0{,}080895','Die Gewichte bestimmen die Einzelvarianzbeiträge und gemeinsam den Kovarianzbeitrag.','Portfoliostandardabweichung als Dezimalrendite, Antworten in Prozent.','allocation'),
 N('75','g','Expected equity and bond returns are 8% and 3%; equity weight is capped at 40%, with no leverage or other assets. Maximum expected return is:',['5%.','6%.','8%.'],['Bei positivem Ertragsabstand ist die höchstzulässige Aktienquote maßgeblich.','Das würde sechzig Prozent Aktien benötigen und die Grenze verletzen.','Das wäre reine Aktienanlage außerhalb des Limits.'],'Z=0{,}40(0{,}08)+0{,}60(0{,}03)=0{,}05','Die maximal zulässige Mischung erreicht fünf Prozent; ein Sechs-Prozent-Ziel wäre bei diesen Eingaben nicht erfüllbar.','Maximaler erwarteter Bruttoertrag pro Jahr unter den angegebenen Grenzen.','feasibility'),
 N('76','g','The bond expected return remains 3% and the portfolio target remains 5%, but expected equity return is revised to 6%. Required equity weight is closest to:',['66.6667%.','40.0000%.','33.3333%.'],['Die nötigen zwei Prozentpunkte werden jetzt durch nur drei Prozentpunkte Klassenabstand geteilt.','Das wäre die frühere Rechnung bei acht Prozent Aktienerwartung.','Das ist das neue Anleihegewicht statt des Aktiengewichts.'],'Z=(0{,}05-0{,}03)/(0{,}06-0{,}03)=2/3','Eine geänderte unsichere Renditeannahme verändert die zum selben Mittelwert benötigte Quote stark; Risiko und Grenzen sind zusätzlich zu prüfen.','Aktiengewicht für genau die geänderte Erwartungsrechnung.','estimation'),
 q('77','g','A strategic allocation is calculated from expected returns, risks and correlations. Its suitability should be assessed:',['Together with the IPS objectives, constraints and implementation conditions.','Die rechnerische Lösung ist nur für ihre Eingaben optimal und muss zum zulässigen Auftrag passen.'],['Solely from how many decimal places the optimized weights contain.','Numerische Genauigkeit ist kein Nachweis belastbarer Schätzungen oder Eignung.'],['From the highest expected-return asset alone, ignoring joint risks.','Gemeinsame Risiken und Anlegergrenzen beeinflussen die geeignete Mischung.'],'expectations'),
 q('78','g','Equity weights rise solely because equity prices outperform bonds. No trade or deliberate view change occurs. This is most accurately described as:',['Market drift rather than necessarily a tactical allocation decision.','Unterschiedliche Kursentwicklungen verändern Gewichte ohne bewusste Entscheidung.'],['A deliberate tactical overweight by definition.','Absicht wird durch die reine Preisbewegung nicht bewiesen.'],['Security selection by the bond manager.','Der Vorgang nennt keinen Tausch einzelner Anleihen.'],'implementation'),
 N('79','g','A portfolio starts at 40% equities and 60% bonds. Equities return 20%, bonds 0%, with no cashflows. End equity weight is:',['44.4444%.','48.0000%.','60.0000%.'],['Aktienwert 48 wird durch den neuen Gesamtwert 108 geteilt.','48 ist der Aktienwert je hundert Startvermögen, nicht der Anteil am neuen Gesamtwert.','Das addiert zwanzig Prozentpunkte zur Startquote statt Vermögensfaktoren zu verwenden.'],'Z=40(1{,}20)/[40(1{,}20)+60]\\approx0{,}444444','Beide Klassenwerte müssen auf den gemeinsamen neuen Bewertungszeitpunkt bezogen werden.','Aktiengewicht nach der Marktbewegung, ohne Handel.','rebalancing'),
 N('80','g','A portfolio starts with 40 equities and 60 bonds. Bonds remain unchanged. The equity return that exactly reaches a 45% equity band boundary is closest to:',['22.7273%.','20.0000%.','12.5000%.'],['Die Gleichung muss auch den veränderten Gesamtwert enthalten.','Das ergibt nur 48 von insgesamt 108 und damit 44,4444 Prozent.','Das setzt den Anstieg von vierzig auf fünfundvierzig isoliert ins Verhältnis und ignoriert den Nenner.'],'Z=\\frac{0{,}45\\cdot60}{40(1-0{,}45)}-1\\approx0{,}227273','Aus 40(1+r) geteilt durch 40(1+r)+60 gleich 0,45 wird der nötige Aktienfaktor bestimmt.','Aktienrendite, die die obere Grenze genau erreicht; ein Handel hängt vom Wortlaut der Regel ab.','rebalancing'),
 N('81','g','Policy weights are 40% equities and 60% bonds; class benchmarks return 10% and 2%. One-period policy return is:',['5.2%.','6.0%.','12.0%.'],['Die Teilbenchmarkrenditen werden mit den vorher vereinbarten Policygewichten kombiniert.','Das wäre eine 50/50-Mischung.','Das addiert die Klassenrenditen ohne Kapitalgewichte.'],'Z=0{,}40(0{,}10)+0{,}60(0{,}02)=0{,}052','Die Rendite gilt für die ausdrücklich einperiodige gewichtete Vergleichsmischung.','Policy-Benchmarkrendite als Dezimalrate.','benchmark'),
 N('82','g','With the same 10% equity and 2% bond returns, actual beginning weights are 50/50 instead of policy 40/60. There is no selection or cost difference. Actual minus policy return is:',['+0.8 percentage points.','+1.0 percentage points.','+6.0 percentage points.'],['Das zusätzliche Aktiengewicht zehn Prozentpunkte wird mit dem Renditeabstand acht Prozentpunkte multipliziert.','Das berücksichtigt den ersetzten Anleiheertrag nicht.','Sechs Prozent ist die tatsächliche Gesamtrendite, nicht deren Differenz zur Policy.'],'Z=[0{,}5(0{,}10)+0{,}5(0{,}02)]-[0{,}4(0{,}10)+0{,}6(0{,}02)]=0{,}008','Der relative Vorteil entsteht in diesem Einperiodenfall aus der anderen Klassenquote; damit ist keine dauerhafte Fähigkeit bewiesen.','Renditedifferenz actual minus policy als Dezimalrate.','benchmark'),
 q('83','g','Highly sensitive optimized weights based on uncertain expected returns most directly motivate:',['Sensitivity analysis and explicit consideration of input uncertainty.','Alternative Annahmen machen sichtbar, wie abhängig die Lösung von der Prognose ist.'],['Treating more displayed decimals as lower economic uncertainty.','Mehr Rechenstellen verbessern keine unsichere Prognose.'],['Discarding all client constraints to preserve the original optimum.','Die Anlegergrenzen bestimmen weiterhin den zulässigen Raum.'],'estimation'),
 q('84','g','A theoretically attractive asset class requires a minimum investment larger than the client entire portfolio. For that client the optimizer result:',['Needs an implementable access and cost assessment before adoption.','Eine rechnerische Klasse ist nicht schon im passenden Umfang tatsächlich zugänglich.'],['Becomes executable solely because expected return is high.','Eine Renditeannahme senkt die Mindestanlage nicht.'],['Removes all other client constraints automatically.','Zugang und andere Grenzen sind zusätzliche gemeinsame Bedingungen.'],'implementation'),
 q('85','h','An investor excludes an activity for personal values while another analyzes its financial costs. The most appropriate conclusion is:',['Values-based restrictions and financial integration can have different purposes.','Die erste Vorgabe regelt Zulässigkeit, die zweite untersucht materielle Wertwirkungen; beide können kombiniert werden.'],['Both approaches necessarily require identical holdings.','Verschiedene Ziele und Regeln können verschiedene Universen ergeben.'],['The financial analysis proves that the values-based objective is invalid.','Eine persönliche zulässige Präferenz wird nicht allein durch eine andere Bewertungsmotivation widerlegt.'],'esg-motives'),
 q('86','h','A hypothetical screen prohibits more than 5% revenue from activity X. Reliable data show 4% for A and 6% for B. Under this rule alone:',['A is not excluded by the threshold, while B is excluded.','Vier liegt unter und sechs über der ausdrücklich vorgegebenen Grenze; weitere Kriterien bleiben separat.'],['Both are excluded because any positive exposure is prohibited.','Das wäre ein anderer Nulltoleranz-Screen.'],['Both are permitted because screening does not affect eligibility.','Ein Screen entscheidet gerade die Zulässigkeit nach Kriterien.'],'screening'),
 q('87','h','A screen explicitly requires verified data before approving a holding. Company C has no reliable data. The manager should:',['Apply the stated missing-data procedure rather than infer compliance from absence.','Fehlende Information ist bei dieser Regel kein Nachweis der Einhaltung.'],['Treat missing information as a verified zero exposure.','Unbekannt und gemessen null sind verschiedene Aussagen.'],['Ignore the screen whenever expected return looks attractive.','Die Bewertung hebt eine gültige Zulässigkeitsgrenze nicht auf.'],'screening'),
 q('88','h','With unchanged risk-return inputs and the same optimization objective, adding a binding exclusion to the feasible set:',['Cannot improve the mathematical optimum merely by removing choices.','Die verbleibenden Möglichkeiten sind eine Teilmenge; der beste frühere Wert konnte diese Möglichkeiten bereits nutzen.'],['Must improve the optimum solely because fewer choices remain.','Eine kleinere Menge erzeugt bei unverändertem Kriterium keinen besseren bestmöglichen Wert.'],['Proves that the excluded strategy will outperform in future markets.','Die Modellmengenbeziehung ist keine sichere Zukunftsprognose.'],'screening'),
 N('89','h','A scenario adds EUR 50 per tonne to 10,000 annual tonnes of emissions. No pass-through, tax, volume change or mitigation occurs. Annual cashflow change is:',['-EUR 500,000.','+EUR 500,000.','-EUR 50,000.'],['Menge mal zusätzlicher Preis ist eine Belastung.','Das kehrt das Vorzeichen der Zusatzkosten um.','Das verwendet nur ein Zehntel der angegebenen Menge.'],'Z=-10\\,000\\cdot50=-500\\,000','Die Annahmen schließen Entlastungen ausdrücklich aus; eine reale Anpassungsreaktion müsste separat modelliert werden.','Änderung des jährlichen freien Cashflows in Euro im beschriebenen Szenario.','integration'),
 N('90','h','A constant annual cashflow reduction of EUR 500,000 starts next year-end and continues forever. At an assumed 10% discount rate, the value change is:',['-EUR 5 million.','-EUR 0.5 million.','-EUR 50 million.'],['Der ewige gleichbleibende Zahlungsrückgang wird durch den positiven Diskontsatz geteilt.','Das berücksichtigt nur eine einzelne ungezinst genannte Jahreszahlung.','Das verwendet einen Diskontsatz von einem statt zehn Prozent.'],'Z=-500\\,000/0{,}10=-5\\,000\\,000','Die Rechnung gilt nur unter der ausdrücklich ewigen konstanten Zahlungsannahme, nicht automatisch für jedes Klimaszenario.','Barwertänderung in Euro unter der genannten ewigen Modellzahlung.','integration'),
 q('91','h','A manager reports three engagement meetings. This establishes most directly:',['An activity count, not by itself achievement of the intended company change.','Aktivität, Ergebnis und ursächlicher Beitrag werden getrennt belegt.'],['That the intended real-world outcome has already occurred.','Die Zahl der Gespräche beweist die Änderung nicht.'],['That all holdings were excluded by screening.','Engagement und Ausschluss sind verschiedene Handlungen.'],'stewardship'),
 N('92','h','A project reports 1,000 connections; 300 replace existing ones and 200 lack verified usage. Under a definition requiring additional verified used connections, the remaining count is:',['500.','700.','1,000.'],['Beide ausdrücklich ausgeschlossenen Gruppen werden abgezogen.','Das entfernt nur die Ersatzanschlüsse und ignoriert die fehlende Nutzungsverifikation.','Das übernimmt die Bruttozahl ohne Definitionsprüfung.'],'Z=1\\,000-300-200=500','Die bereinigte Ergebniszahl zeigt noch nicht, ob gerade das Anlegerkapital die Veränderung verursacht hat.','Anzahl zusätzlicher verifiziert genutzter Anschlüsse nach der ausdrücklich gegebenen Definition.','impact'),
 q('93','h','A project has verified positive outcomes. To claim that the investor caused those outcomes, the analyst additionally needs to examine:',['The counterfactual, alternative funding and the investor contribution.','Ein beobachtetes Ergebnis und dessen ursächliche Zurechnung sind verschiedene Aussagen.'],['Only the fund name and current share price.','Diese Größen belegen keinen ursächlichen Wirkungsbeitrag.'],['Whether any ESG rating is available, regardless of its scope.','Ein unspezifisches Rating ersetzt keine Prüfung des behaupteten Beitrags.'],'impact'),
 q('94','h','A fund buys companies exposed to water technology but has no stated outcome intention or measurement. It is most clearly described as:',['A thematic exposure, without enough information to establish an impact mandate.','Ein Thema allein belegt weder ein beabsichtigtes positives Ergebnis noch dessen Messung.'],['A demonstrated impact investment solely because of the sector.','Die Sektorexposition genügt nicht als Wirkungsnachweis.'],['Proof that financial return is irrelevant.','Auch eine thematische Anlage hat wirtschaftliche Risiko- und Ertragseigenschaften.'],'impact'),
 q('95','h','ESG cashflow reductions are already explicitly modeled. A second identical valuation deduction is proposed without a separate risk rationale. The main concern is:',['Double counting the same economic effect.','Ein bereits erfasster Zahlungsrückgang darf nicht nochmals als identischer pauschaler Abzug wirken.'],['That ESG factors can never affect valuation.','Materielle Faktoren können gerade über Cashflows und Risiken relevant sein.'],['That every adjustment must instead be applied only to the fund name.','Ein Produktname ist kein Bewertungsmodell.'],'integration'),
 q('96','h','An ESG-constrained benchmark is used. The manager should still assess:',['Consistency with the investor absolute objectives, concentration limits and remaining constraints.','Ein passender relativer Vergleich ersetzt die übrigen Anlegerziele und Risikogrenzen nicht.'],['Only relative performance, even if the client fixed payment becomes unfunded.','Die Verpflichtung bleibt unabhängig vom Benchmarkrang relevant.'],['That the benchmark eliminates all data and methodology uncertainty.','Auch gefilterte Indizes können Datenlücken und veränderte Methoden enthalten.'],'esg-controls')
];
const exam=(n,pool,obj,stem,a,b,c,section,solution)=>Q('ips-exam-'+n,id,'portfolio',pool,obj,stem,[a,b,c],0,solution,{section});
module.exports.push(
 exam('a1','mock-a','a b','An adviser takes over a family trust. Existing notes alternate between nominal capital preservation and real purchasing-power growth; two committees claim authority over allocation. The most appropriate first step is to:',['Clarify and document the objectives, mandate scope and authorized decision responsibilities.','Uneinheitliche Ziele und Zuständigkeiten werden vor einer Umsetzungsentscheidung geklärt.'],['Adopt the best recent fund and infer the objective from its return.','Ein Produkt liefert weder die fehlende Zieldefinition noch eine Delegation.'],['Allow both committees to change the policy independently without a priority rule.','Widersprüchliche unkoordinierte Befugnisse lösen die Governance-Lücke nicht.'],'scope',['Nominaler Erhalt und reale Kaufkraft sind unterschiedliche Ergebnisgrößen. Der übernehmende Berater muss klären, welcher Betrag auf welcher Basis und zu welchem Zeitpunkt geschützt oder aufgebaut werden soll. Die bisherige Wortwahl reicht als einheitlicher Auftrag nicht aus.','Zusätzlich wird festgelegt, wer strategische Änderungen genehmigt und wie die Dokumentversion gilt. Erst damit lassen sich spätere Anlageentscheidungen und Änderungen überprüfen. Eine attraktive vergangene Fondsrendite ersetzt keine dieser Informationen.']),
 exam('a2','mock-a','c d','A client can tolerate large losses emotionally but needs nearly all liquid wealth for a fixed payment next year. The client demands a high expected return. The adviser should most appropriately:',['Recognize limited capacity and reassess the funding plan rather than let willingness override the obligation.','Die feste Zahlung begrenzt die wirtschaftliche Verlustfähigkeit trotz hoher Bereitschaft.'],['Average the high willingness and low capacity into an automatic medium-risk allocation.','Die Kategorien haben keine gemeinsame kalibrierte Skala und die Zahlung bleibt fest.'],['Increase equity risk because the required return establishes the ability to recover.','Ein Renditebedarf ist keine zusätzliche Ressource oder garantierte Erholung.'],'conflict',['Die psychologische Haltung beantwortet, wie der Anleger Unsicherheit empfindet. Die finanzielle Fähigkeit beantwortet hier, ob nach einem ungünstigen Verlauf die feste Zahlung noch möglich ist. Hohe Bereitschaft kann die fehlende Ressource nicht ersetzen.','Der hohe Renditebedarf kann gerade auf einen widersprüchlichen Plan hinweisen. Beiträge, Ausgabenumfang, Termin oder andere tatsächlich zulässige Finanzierungsmöglichkeiten müssen geprüft werden. Eine ungeklärte höhere Quote oder ein arithmetischer Durchschnitt der Kategorien wäre keine begründete Lösung.']),
 exam('a3','mock-a','e f','A perpetual foundation funds grants each quarter. A proposed portfolio treats an infrequently valued private fund as cash-like because its reported volatility is low. The most appropriate response is to:',['Assess redemption and capital-call terms, valuation timing and the quarterly payment needs together.','Dauerexistenz und geglättete Daten schaffen keine zeitgerechten liquiden Mittel.'],['Accept the classification because perpetual existence eliminates withdrawal needs.','Die regelmäßigen Förderzahlungen bleiben fällig.'],['Infer daily liquidity directly from the low reported volatility.','Bewertungsschwankung und vertraglicher Ausstiegsweg sind verschiedene Eigenschaften.'],'alternatives',['Der lange Bestandshorizont der Stiftung und die kurzen Zahlungstermine bestehen gleichzeitig. Für die Förderungen zählt, wann Mittel wirklich verfügbar sind und welche Verpflichtungen oder Kapitalabrufe zusätzlich eintreten können.','Eine selten aktualisierte Bewertung kann Schwankungen glätten und gemeinsame Markteinflüsse zeitversetzt abbilden. Der niedrige Messwert ist deshalb weder ein Beweis für geringe wirtschaftliche Risiken noch ein tägliches Rückgaberecht. Die Anlageklassenabgrenzung muss diese Eigenschaften berücksichtigen.']),
 exam('a4','mock-a','g h','A manager knowingly exceeds an approved activity-exclusion threshold to buy an attractive security and then selects a new unrestricted benchmark after favorable returns. The most appropriate assessment is:',['Favorable performance does not cure the restriction breach or justify a retrospective benchmark change.','Mandatstreue und eine vorher passende Vergleichsgrundlage werden getrennt vom Ergebnis geprüft.'],['The profit makes the holding compliant with the original screen.','Ein späterer Gewinn verändert die ursprünglich gültige Zulässigkeitsregel nicht.'],['Any broad benchmark is interchangeable once the manager return is known.','Universum und Messbasis müssen zum vereinbarten Auftrag passen.'],'esg-controls',['Der Screen ist eine konkret genehmigte Grenze des zulässigen Universums. Eine attraktive Bewertung kann eine Analyse begründen, hebt diese Grenze aber nicht eigenmächtig auf. Ein wirtschaftlicher Gewinn ist kein rückwirkender Änderungsbeschluss.','Auch die Ergebnisbeurteilung braucht die zum Auftrag passende vorher definierte Benchmark. Ein späterer Wechsel nur wegen der günstigeren Darstellung verschleiert die ursprüngliche Entscheidung. Eine zulässige Policyänderung muss mit Zuständigkeit und Zeitpunkt dokumentiert werden.']),
 Q("ips-exam-b1",
   "ips",
   "portfolio",
   "mock-b",
   "a b",
   "A client moves abroad and adds a large dependent-care commitment. The existing IPS contains the former tax status and no event-driven review rule. The adviser should first:",
   [["Reassess the material circumstances and document the authorized updated objectives and constraints.","Neue Steuerumstände und Verpflichtungen können den bisherigen Auftrag verändern."],["Wait until the scheduled annual IPS review before assessing the new tax status and dependent-care obligation.","Die neuen Umstände können Ziele und Grenzen bereits jetzt materiell verändern. Eine Routinefrist ersetzt keine zeitnahe Prüfung und dokumentierte, autorisierte Anpassung."],["Assume the same tax treatment automatically applies in the new country.","Konkrete Steuerregeln hängen vom geltenden Recht und Sachverhalt ab."]],
   0,
   ["Die neue Lebenslage betrifft mehr als eine Marktprognose: Eine andere steuerliche Situation und neue Zahlungsverpflichtungen können die verfügbare Rendite, Liquidität und Tragfähigkeit verändern. Diese Informationen werden erhoben und nicht aus dem alten Dokument fortgeschrieben.","Anschließend werden erforderliche Änderungen mit dem zuständigen Genehmigungsweg und ihrer Version dokumentiert. Der Fall verlangt keine Behauptung einer bestimmten nationalen Steuerregel. Er verlangt die Überprüfung der tatsächlich anwendbaren Umstände."],
   {"section":"discipline"}),
 Q("ips-exam-b2",
   "ips",
   "portfolio",
   "mock-b",
   "c d",
   "An investor has substantial uncommitted resources but says a plausible 15% drawdown would trigger an immediate abandonment of the strategy. The portfolio is intended to meet a distant real goal. The adviser should:",
   [["Clarify informed willingness and the real objective while separately assessing financial capacity.","Fähigkeit, Bereitschaft und reale Zielbasis bleiben unterschiedliche Prüfungen."],["Use the maximum risk affordable financially without discussing the reaction.","Das ignoriert eine mögliche psychologische Begrenzung und den Planabbruch."],["Infer high willingness from the distant goal and treat the stated drawdown reaction as irrelevant to implementation.","Ein langer Horizont kann finanzielle Risikotragfähigkeit stützen. Er widerlegt aber nicht die ausdrücklich genannte Bereitschaft, die Strategie bei Verlust abzubrechen."]],
   0,
   ["Ein großer finanzieller Puffer kann hohe wirtschaftliche Verlustfähigkeit ermöglichen. Die geschilderte Reaktion ist trotzdem relevant, weil eine vorzeitige Aufgabe den langfristigen Plan verändern kann. Mit verständlichen Geldbeträgen und Szenarien werden Wissen und tatsächliche Bereitschaft geklärt.","Das reale Ziel beschreibt einen Warenkorb und benötigt eine passende Inflationsbasis. Es darf nicht stillschweigend als nominal identisch behandelt werden. Die endgültige Risikoentscheidung muss sowohl den geklärten Auftrag als auch die verbleibende Bereitschaft und Tragfähigkeit berücksichtigen."],
   {"section":"willingness"}),
 Q("ips-exam-b3",
   "ips",
   "portfolio",
   "mock-b",
   "e f",
   "A household buys a EUR-listed world equity ETF alongside a US equity fund and expects the combination to provide two disjoint, currency-risk-free classes. The most appropriate analysis is to:",
   [["Look through the holdings, overlap and currency exposures in relation to the household obligations.","Börsenwährung und zwei Produktnamen beweisen keine unabhängigen oder währungssicheren Expositionen."],["Use the world-equity and US-equity fund categories as evidence that their holdings do not overlap.","Ein Weltaktienfonds kann umfangreiche US-Aktien halten. Produktkategorien sind kein Nachweis überschneidungsfreier Bestände oder unabhängiger Risikotreiber."],["Treat EUR listing as a hedge of every underlying foreign exposure.","Eine Notierungswährung ist kein Sicherungsvertrag."]],
   0,
   ["Der Weltfonds kann bereits US-Aktien halten. Das äußere Fondsgewicht wird mit den inneren Regionalgewichten multipliziert, damit die tatsächliche Überlappung sichtbar wird. Zwei Vehikel müssen deshalb nicht zwei getrennte wirtschaftliche Anlageklassen bilden.","Eine Euro-Notierung betrifft den Handelspreis und beseitigt nicht automatisch fremde Risikotreiber. Die tatsächlichen Werte und gegebenenfalls vorhandenen Sicherungen werden auf die Rechnungseinheit und die Fälligkeiten der Haushaltsverpflichtungen bezogen."],
   {"section":"overlap"}),
 Q("ips-exam-b4",
   "ips",
   "portfolio",
   "mock-b",
   "g h",
   "An investor seeks a measurable positive social outcome but also imposes liquidity and concentration limits. A thematic fund reports meetings and gross project counts. The most appropriate next step is to:",
   [["Specify the intended outcome, credible measures and implementation rules, and check the fund against the full mandate.","Themenname, Aktivitäten und Bruttozahlen belegen den gewünschten Beitrag nicht allein."],["Select the thematic fund first and review liquidity and concentration only after the position has been purchased.","Die Grenzen sind Bestandteil des bestehenden Mandats. Vor dem Kauf muss geprüft werden, ob die Umsetzung sowohl das Wirkungsziel als auch die Finanzierungs- und Konzentrationsanforderungen erfüllt."],["Use the gross project count as evidence of the investor’s additional social contribution without a counterfactual assessment.","Bruttoaktivität zeigt nicht, welcher zusätzliche Effekt durch den Anleger entsteht. Ergebnis, Zurechnung und gegebenenfalls das plausible Geschehen ohne den Beitrag müssen nachvollziehbar beurteilt werden."]],
   0,
   ["Die Zielsetzung verlangt eine klare beabsichtigte Veränderung und nachvollziehbare Messung. Bruttozahlen können Ersatz, nicht belegte Nutzung und andere Einschränkungen enthalten. Gespräche dokumentieren zunächst Aktivitäten; ein ursächlicher Beitrag braucht eine zusätzliche Analyse.","Die passende Wirkungskonzeption ist außerdem kein Ersatz für wirtschaftliche Eignung. Anlagezugang, Liquidität, Konzentration, Kosten und Renditebedarf werden weiterhin gemeinsam gegen den Auftrag geprüft. Gegebenenfalls müssen Ziel oder Umsetzung präzisiert werden."],
   {"section":"impact"})
);
